'use client';

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Formik } from "formik";

export default function AddPost() {
  return (
    <div className="p-5">
      <Formik
        initialValues={{
          title: '',
          detail: '',
          image: ''
        }}
        onSubmit={(val) => {
          try {

          } catch (err) {

          }

        }}
      >


        {({ handleChange, handleSubmit, values }) => (

          <form onSubmit={handleSubmit} className="max-w-lg space-y-5">

            <div>
              <Input
                name="title"
                onChange={handleChange}
                value={values.title}
                placeholder="Title"
              />
            </div>
            <div>
              <Input
                value={values.detail}
                onChange={handleChange}
                name="detail"
                placeholder="Detail"
              />
            </div>
            <div>
              <Input
                value={values.image}
                onChange={handleChange}
                name="image"
                placeholder="Image"
              />
            </div>
            <Button type="submit">Submit</Button>
          </form>



        )}



      </Formik>





    </div>
  )
}
